import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  delayRender,
  continueRender,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  // Use Remotion's delayRender to pause rendering until fonts are loaded
  // This prevents flickering (FOUT) during export.
  const [handle] = React.useState(() => delayRender("Loading Google Fonts"));

  React.useEffect(() => {
    const uniqueFonts = [...new Set(fonts.map((f) => f.trim()))].sort();
    const unloaded = uniqueFonts.filter(
      (font) =>
        !document.querySelector(`link[href*="${font.replace(/\s+/g, "+")}"]`)
    );

    const waitForFontsAndContinue = () => {
      document.fonts.ready
        .then(() => continueRender(handle))
        .catch(() => continueRender(handle)); // Continue even if font parsing fails
    };

    if (unloaded.length === 0) {
      waitForFontsAndContinue();
      return;
    }

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    link.onload = waitForFontsAndContinue;
    link.onerror = () => continueRender(handle); // Continue rendering on network error

    document.head.appendChild(link);
  }, [fonts.join("|"), handle]);
};
{/* End Google Fonts Loader */}



