const PromptBoxAnimation: React.FC<PromptBoxAnimationProps> = ({
  backgroundColor = "#09090b",
  transparentBackground = true,
  durationInSeconds = 10,
  boxBackgroundColor = "#16151A",
  boxStrokeColor = "#302D3A",
  boxTitle = "Describe with",
  promptText = "iOS calendar showing October 2024. Red strikethrough lines draw across dates 12–24 one by one, fast and sharp. Transparent background.",
  framesPerCharacter = 2,
  buttonText = "Generate",
  buttonColor = "#E879F9",
  titleFontSize = 24,
  textFontSize = 36,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Parser safe background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Entrance Animation
  const entranceProgress = spring({
    frame,
    fps,
    config: {
      damping: 14,
      stiffness: 100,
      mass: 0.8,
    },
  });

  const boxOpacity = interpolate(entranceProgress, [0, 1], [0, 1]);
  const boxScale = interpolate(entranceProgress, [0, 1], [0.96, 1]);
  const boxY = interpolate(entranceProgress, [0, 1], [60, 0]);

  // Typing Animation
  const startTypingFrame = 15;
  const charsToShow = Math.max(
    0,
    Math.floor((frame - startTypingFrame) / framesPerCharacter)
  );
  const displayedText = promptText.substring(0, charsToShow);
  const isTypingFinished = charsToShow >= promptText.length;

  // Cursor Timing and Calculations
  const endTypingFrame = startTypingFrame + promptText.length * framesPerCharacter;
  const cursorMoveStart = endTypingFrame + 15; // Wait half a second after typing
  const clickStart = cursorMoveStart + 40; // Allow spring to settle before clicking

  // Cursor Movement
  const cursorMoveProgress = spring({
    frame: Math.max(0, frame - cursorMoveStart),
    fps,
    config: { damping: 14, stiffness: 80, mass: 0.8 },
  });

  // Coordinates relative to the outer container box
  const cursorRight = interpolate(cursorMoveProgress, [0, 1], [-200, 120]); // Starts off-screen right
  const cursorTop = interpolate(cursorMoveProgress, [0, 1], [600, 50]); // Starts below box
  const cursorOpacityEntrance = interpolate(frame, [cursorMoveStart, cursorMoveStart + 5], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Click Animation States
  let btnScale = 1;
  let cursorClickScale = 1;

  if (frame >= clickStart && frame < clickStart + 5) {
    btnScale = interpolate(frame, [clickStart, clickStart + 4], [1, 0.92], { extrapolateRight: "clamp" });
    cursorClickScale = interpolate(frame, [clickStart, clickStart + 4], [1, 0.85], { extrapolateRight: "clamp" });
  } else if (frame >= clickStart + 5) {
    btnScale = interpolate(frame, [clickStart + 5, clickStart + 15], [0.92, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
    cursorClickScale = interpolate(frame, [clickStart + 5, clickStart + 15], [0.85, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  }

  // Ripple Effect on Button
  const showRipple = frame >= clickStart;
  const rippleScale = showRipple ? interpolate(frame, [clickStart, clickStart + 20], [0.5, 1.8], { extrapolateRight: "clamp" }) : 0;
  const rippleOpacity = showRipple ? interpolate(frame, [clickStart, clickStart + 20], [0.4, 0], { extrapolateRight: "clamp" }) : 0;

  // Blinking Cursor (Text)
  const textCursorBlinkRate = isTypingFinished ? 30 : 15;
  const textCursorOpacity = frame % textCursorBlinkRate < textCursorBlinkRate / 2 ? 1 : 0;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Outer Container Matching Reference Style */}
      <div
        style={{
          position: "relative", // Added for anchoring the mouse cursor
          width: width * 0.85,
          background: boxBackgroundColor,
          borderRadius: "24px",
          padding: "32px 40px",
          border: `1.5px solid ${boxStrokeColor}`,
          opacity: boxOpacity,
          transform: `scale(${boxScale}) translateY(${boxY}px)`,
          display: "flex",
          flexDirection: "column",
          gap: "40px",
          boxShadow: "0 20px 40px rgba(0,0,0,0.4)",
        }}
      >
        {/* Header Row */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            justifyContent: "space-between",
          }}
        >
          {/* Left Controls */}
          <div style={{ display: "flex", alignItems: "center", gap: "24px" }}>
            <span
              style={{
                color: "#ffffff",
                fontSize: `${titleFontSize}px`,
                fontWeight: 600,
                letterSpacing: "-0.01em",
              }}
            >
              {boxTitle}
            </span>
            <DropdownMock label="Text" fontSize={titleFontSize * 0.85} borderColor={boxStrokeColor} />
            
            <span
              style={{
                color: "#ffffff",
                fontSize: `${titleFontSize}px`,
                fontWeight: 600,
                letterSpacing: "-0.01em",
              }}
            >
              Aspect Ratio
            </span>
            <DropdownMock label="16:9" fontSize={titleFontSize * 0.85} showMonitor borderColor={boxStrokeColor} />
          </div>

          {/* Right Button (Pink Generate) */}
          <div
            style={{
              position: "relative",
              overflow: "hidden", // Constrain ripple effect
              backgroundColor: buttonColor,
              color: "#000000",
              padding: "16px 32px",
              borderRadius: "16px",
              display: "flex",
              alignItems: "center",
              gap: "12px",
              fontSize: `${titleFontSize}px`,
              fontWeight: 600,
              transform: `scale(${btnScale})`,
              transformOrigin: "center",
              transition: "none",
            }}
          >
            <SparklesIcon size={titleFontSize * 1.1} />
            <span style={{ position: "relative", zIndex: 2 }}>{buttonText}</span>
            
            {/* Ripple Effect Element */}
            {showRipple && (
              <div
                style={{
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  width: "150px",
                  height: "150px",
                  marginTop: "-75px",
                  marginLeft: "-75px",
                  background: "rgba(255, 255, 255, 0.6)",
                  borderRadius: "50%",
                  transform: `scale(${rippleScale})`,
                  opacity: rippleOpacity,
                  pointerEvents: "none",
                  zIndex: 1,
                }}
              />
            )}
          </div>
        </div>

        {/* Typing Text Area */}
        <div style={{ minHeight: "240px", position: "relative" }}>
          <p
            style={{
              margin: 0,
              color: "#f4f4f5",
              fontSize: `${textFontSize}px`,
              lineHeight: 1.5,
              fontWeight: 500,
              letterSpacing: "-0.01em",
              whiteSpace: "pre-wrap",
            }}
          >
            {displayedText}
            {/* Blinking Cursor */}
            <span
              style={{
                display: "inline-block",
                width: "3px",
                height: `${textFontSize + 4}px`,
                backgroundColor: "#ffffff",
                marginLeft: "6px",
                verticalAlign: "middle",
                opacity: textCursorOpacity,
                transform: "translateY(-4px)",
              }}
            />
          </p>
        </div>

        {/* Footer Row */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end" }}>
          {/* Prompting Guides Button */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: "12px",
              padding: "12px 20px",
              border: `1.5px solid ${boxStrokeColor}`,
              borderRadius: "12px",
              background: "rgba(255,255,255,0.02)",
              color: "#a1a1aa",
              fontSize: `${titleFontSize * 0.8}px`,
              fontWeight: 500,
            }}
          >
            <LightbulbIcon size={titleFontSize * 0.9} />
            <span>Prompting Guides</span>
            <ChevronDownIcon size={titleFontSize * 0.9} />
          </div>
        </div>

        {/* Mouse Pointer Cursor */}
        <div
          style={{
            position: "absolute",
            right: `${cursorRight}px`,
            top: `${cursorTop}px`,
            transform: `scale(${cursorClickScale})`,
            transformOrigin: "top left",
            zIndex: 50,
            pointerEvents: "none",
            opacity: cursorOpacityEntrance,
          }}
        >
          <CursorIcon size={40} />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PromptBoxAnimation;